"""Get minimal value of list and its count."""
def min_count1(lst: list[int]) -> list[int] {
    if len(lst) == 0 {
        return [];
    }
    count = 0;
    min_value = lst[0];
    for num in lst {
        if num == min_value {
            count += 1;
        } elif num < min_value {
            count = 1;
            min_value = num;
        }
    }
    return [min_value, count];
}

"""
        Create an octave-repeating scale from a tonic note
        and a pattern of intervals

        Args:
            tonic: root note (midi note number)
            pattern: pattern of intervals (list of numbers representing
            intervals in semitones)
            octave: span of scale (in octaves)

        Returns:
            list of midi notes in the scale
    """
def create_scale(tonic: int, pattern: list[int], octave: int = 1) -> list[int] {
    assert sum(pattern) == 12;
    scale = [tonic];
    note = tonic;
    for o in range(octave) {
        for i in pattern {
            note += i;
            if note <= 127 {
                scale.append(note);
            }
        }
    }
    return scale;
}

"""IOBES -> IOB."""
def iobes_iob(tags: list[str]) -> list[str] {
    new_tags = [];
    for tag in tags {
        if tag == 'rel' {
            new_tags.append(tag);
        } else {
            match tag.split('-')[0] {
                case 'B':
                    new_tags.append(tag);
                case 'I':
                    new_tags.append(tag);
                case 'S':
                    new_tags.append(tag.replace('S-', 'B-'));
                case 'E':
                    new_tags.append(tag.replace('E-', 'I-'));
                case 'O':
                    new_tags.append(tag);
                case _:
                    raise Exception('Invalid format!');
            }
        }
    }
    return new_tags;
}

