        ret = code;
        i = code.rfind('<a href="');
        if i > -1 {
            j = code.find('"', i + 9);
            k = code.find('>', j);
            l = code.find('<', k);
            ret = code[:i] + '(' + code[i + 9:j] + ' : ' + code[k + 1:l] + ')' + code[l + 4:];
        }
        return (i, ret);
    }
    i = 1;
    ret = code;
    while i > -1 {
        (i, ret) = link_as_text(ret);
    }
    return ret;
}

""" Create a string representation of a numpy array with less precision
