"""Calculate new minimum dimensions and corresponding scalar."""
def calc_new_dimensions(max_size: int, width: int, height: int) -> tuple[tuple[int, int], float] {
    width_scalar = max_size / width;
    height_scalar = max_size / height;
    best_fit_scalar = min(width_scalar, height_scalar);
    dimensions = (int(width * best_fit_scalar), int(height * best_fit_scalar));
    return (dimensions, best_fit_scalar);
}

"""Adjusts a given filename so it ends with the proper extension."""
def adjust_filename_to_globs(filename: str, globs: list[str | None]) -> str {
    if globs {
        possible_fns: list[str] = [];
        for `glob in globs {
            if `glob is not None {
                extension = `glob[1:];
                if filename[(len(filename) - len(extension)):].lower() != extension.lower() {
                    possible_fns.append(f"{filename}{`glob[1:]}");
                } else {
                    return filename;
                }
            }
        }
        return possible_fns[0];
    }
    return filename;
}

