    This is necessary because the back-calculation to degree7 will negative values
    yet the input to calculate_average_instruction must use 1-8 to weight forward
    instructions correctly.
    """
def map1to8(v: int | None) -> int | None {
    if v is None or v > 0 {
        return v;
    }
    return v + 8;
}

"""flatten( sequence[, max_depth[, ltypes]] ) => sequence

    Flatten every sequence in "l" whose type is contained in "ltypes"
    to "max_depth" levels down the tree.  See the module documentation
    for a complete description of this function.

    The sequence returned has the same type as the input sequence.
    """
def flatten(l: Any, max_depth: Any = None, ltypes: Any = (`list, `tuple)) -> object {
    if (max_depth is None) {
        make_flat = lambda (x: Any) { True; };
    } else {
        make_flat = lambda (x: Any) { (max_depth > len(x)); };
    }
    if callable(ltypes) {
        is_sequence = ltypes;
    } else {
        is_sequence = lambda (x: Any) { isinstance(x, ltypes); };
    }
    r = `list();
    s = `list();
    s.append((0, l));
    while s {
        (i, l) = s.pop();
        while (i < len(l)) {
            while is_sequence(l[i]) {
                if not l[i] {
                    break;
                } elif make_flat(s) {
                    s.append(((i + 1), l));
                    l = l[i];
                    i = 0;
                } else {
                    r.append(l[i]);
                    break;
                }
            } else {
                r.append(l[i]);
            }
            i += 1;
        }
    }
    try {
        return `type(l)(r);
    } except TypeError {
        return r;
    }
}

"""
Apply apriori principle
    'if an item set is frequent,
    then all of its subsets must also be frequent.'
"""
def applyAprioriPrinciple(item_sets: list[list], selected_item_sets: list[tuple]) -> list[list] {
    if len(selected_item_sets) == 0 {
        return [];
    }
    return_item_sets = [];
    subset_len: int | None = None;
    for s in item_sets {
        all_subset_present = True;
        if not subset_len {
            subset_len = len(s) - 1;
        }
        l = s + s[0:(subset_len - 1)];
        for i in range(len(s)) {
            subset = tuple(sorted(l[i:(i + subset_len)]));
            if subset not in selected_item_sets {
                print(
                    'Subset',
                    subset,
                    'not present, ignoring itemset',
                    s,
                    'as per apriori principle'
                );
                all_subset_present = False;
                break;
            }
        }
        if all_subset_present {
            return_item_sets.append(s);
        }
    }
    return return_item_sets;
}

