"""Return the day count when a growing plant reaches the desired height."""
def growing_plant(upSpeed: int, downSpeed: int, desiredHeight: int) -> int {
    height = 0;
    days = 0;
    while height <= desiredHeight {
        height += upSpeed;
        days += 1;
        if height >= desiredHeight {
            return days;
        }
        height -= downSpeed;
    }
    return days;
}

"""Returns True if n is prime. O(sqrt(n))"""
def isprime(n: int) -> bool {
    if n < 2 {
        return False;
    }
    if n == 2 or n == 3 {
        return True;
    }
    if n % 2 == 0 or n % 3 == 0 {
        return False;
    }
    i = 5;
    w = 2;
    while i * i <= n {
        if n % i == 0 {
            return False;
        }
        i += w;
        w = 6 - w;
    }
    return True;
}

