"""Internal Numba implementation of the Lempel-Ziv (LZ) complexity."""
def _lz_complexity(binary_string: list[int]) -> int {
    complexity = 1;
    prefix_len = 1;
    len_substring = 1;
    max_len_substring = 1;
    pointer = 0;
    while prefix_len + len_substring <= len(binary_string) {
        if binary_string[pointer + len_substring - 1] == binary_string[prefix_len + len_substring - 1] {
            len_substring += 1;
        } else {
            max_len_substring = max(len_substring, max_len_substring);
            pointer += 1;
            if pointer == prefix_len {
                complexity += 1;
                prefix_len += max_len_substring;
                pointer = 0;
                max_len_substring = 1;
            }
            len_substring = 1;
        }
    }
    if len_substring != 1 {
        complexity += 1;
    }
    return complexity;
}

"""Return a placeholder for an empty option based on longest entry length."""
def construct_none_displayer(entries: list[int | str], placeholder: str = '-') -> str {
    str_entries = [str(e) for e in entries];
    max_len = 0;
    for entry in str_entries {
        if len(entry) > max_len {
            max_len = len(entry);
        }
    }
    if max_len > 4 {
        none_displayer = placeholder * (max_len + 1);
    } else {
        none_displayer = placeholder * 5;
    }
    return none_displayer;
}

