    Time complexity: O(1).
    Space complexity: O(1).
    """
def consecutive_ducks2(n: int) -> bool {
    if n == 2 {
        return False;
    }
    if n % 2 == 1 {
        return True;
    }
    if n & (n - 1) == 0 {
        return False;
    }
    return True;
}

"""
    :type digits: List[int]
    :rtype: List[int]
    """
def plusOne(digits: Any) -> object {
    digits[-1] = digits[-1] + 1;
    res = [];
    ten = 0;
    i = len(digits) - 1;
    while ((i >= 0) or (ten == 1)) {
        sum = 0;
        if (i >= 0) {
            sum += digits[i];
        }
        if ten {
            sum += 1;
        }
        res.append((sum % 10));
        ten = sum / 10;
        i -= 1;
    }
    return res[::-1];
}

