"""Integrate fx from x_min to x_max using the trapezoidal rule."""
def trapezoidal(
    f: Callable[[float], float],
    x_min: float,
    x_max: float,
    n: int = 1000
) -> float {
    h = (x_max - x_min) / n;
    jum = 0.5 * f(x_min);
    for i in range(1, n) {
        xi = x_min + h * i;
        jum = jum + f(xi);
    }
    jum = jum + 0.5 * f(x_max);
    return jum * h;
}

"""
https://stackoverflow.com/questions/480214/how-do-you-remove-duplicates-from-a-list-whilst-preserving-order
"""
def remove_dups[T](seq: list[T]) -> list[T] {
    seen = set();
    seen_add = seen.add;
    return [x for x in seq if not (x in seen or seen_add(x))];
}

"""
Pad the collection `coll` with `padding` items
until it reaches the length of `size`.
By default do padding in the beginning (on the left side).
"""
def pad[T](coll: list[T], size: int, padding: T, left: bool = True) -> list[T] {
    padding_size = size - len(coll);
    if padding_size <= 0 {
        return coll;
    }
    pad_items = [padding] * padding_size;
    new_list = list(coll);
    return pad_items + new_list if left else new_list + pad_items;
}

