"""
Creates an adjacency list and indegree counts from an order
(vertex count) and edges.
"""
def build_adj_and_indegrees(order: int, edges: list[tuple[int, int]]) -> tuple[list[list[int]], list[int]] {
    adj = [[] for _ in range(order)];
    indegs = [0] * order;
    for (src, dest) in edges {
        adj[src].append(dest);
        indegs[dest] += 1;
    }
    return (adj, indegs);
}

glob POPCOUNT_MASK_55 = 0x5555555555555555;
glob POPCOUNT_MASK_33 = 0x3333333333333333;
glob POPCOUNT_MASK_0F = 0x0F0F0F0F0F0F0F0F;
glob POPCOUNT_MASK_7F = 0x0000007F;

"""Popcount."""
def popcount(n: int) -> int {
    n -= (n >> 1) & POPCOUNT_MASK_55;
    n = (n & POPCOUNT_MASK_33) + ((n >> 2) & POPCOUNT_MASK_33);
    n = (n + (n >> 4)) & POPCOUNT_MASK_0F;
    n = n + (n >> 8);
    n = n + (n >> 16);
    n = n + (n >> 32);
    return n & POPCOUNT_MASK_7F;
}

