""" expand the segment"""
def expand_segment(
    num_frames: Any, num_target_frames: Any, start_frame: Any, stop_frame: Any
) -> object {
    num_frames_seg = (stop_frame - start_frame) + 1;
    changes = False;
    num_target_frames = min(num_target_frames, num_frames);
    if (num_frames_seg < num_target_frames) {
        while True {
            if (start_frame > 0) {
                start_frame -= 1;
                num_frames_seg += 1;
                changes = True;
            }
            if (num_frames_seg == num_target_frames) {
                break;
            }
            if (stop_frame < (num_frames - 1)) {
                stop_frame += 1;
                num_frames_seg += 1;
                changes = True;
            }
            if (num_frames_seg == num_target_frames) {
                break;
            }
        }
    }
    return (start_frame, stop_frame, changes);
}

"""Return merged, sorted array and number of split inversions."""
def _merge_and_count_split_inv(left: Any, right: Any) -> object {
    (max_left, max_right) = (len(left), len(right));
    if ((max_left == 0) or (max_right == 0)) {
        return ((left + right), 0);
    }
    merged = [];
    inv_count = 0;
    i = j=0;
    while ((i < max_left) and (j < max_right)) {
        if (left[i] <= right[j]) {
            merged.append(left[i]);
            i += 1;
        } else {
            merged.append(right[j]);
            j += 1;
            inv_count += max_left - i;
        }
    }
    while (i < max_left) {
        merged.append(left[i]);
        i += 1;
    }
    while (j < max_right) {
        merged.append(right[j]);
        j += 1;
    }
    return (merged, inv_count);
}

