    suffixes["K"] = 1000 * suffixes["B"];
    suffixes["M"] = 1000 * suffixes["K"];
    suffixes["G"] = 1000 * suffixes["M"];
    suffixes["T"] = 1000 * suffixes["G"];
    suffix = strformat[-1];
    amount = int(strformat[:-1]);
    return amount * suffixes[suffix];
}

