  """
def calculateBallRegion(ballCoordinate: list[float], robotCoordinate: list[float]) -> int {
    ballRegion = 0;
    if ballCoordinate[0] > robotCoordinate[0] {
        if ballCoordinate[1] > robotCoordinate[1] {
            ballRegion = 1;
        } else {
            ballRegion = 4;
        }
