"""Get result of multiplying a final horizontal position by a final depth
    taking into account the aim value;
    commands(list of list[direction(str), steps(int)]): instructions"""
def get_correct_final_coordinates_product(commands: Any) -> object {
    hor = 0;
    dep = 0;
    aim = 0;
    for com in commands {
        if (com[0] == "up") {
            aim -= com[1];
        } elif (com[0] == "down") {
            aim += com[1];
        } else {
            hor += com[1];
            dep += com[1] * aim;
        }
    }
    return (hor * dep);
}

"""Build the index (P x D) -> N for all interactors of the current protein."""
def build_index(interactors: list[tuple[str, str]]) -> dict[tuple[str, str], int] {
    index = dict();
    sorted_interactors = sorted(list(interactors));
    for (p, d) in sorted_interactors {
        index[(p, d)] = sorted_interactors.index((p, d));
    }
    return index;
}

"""Question 14.1: Compute the intersection of two sorted arrays."""
def compute_intersection(arr_1: list[int], arr_2: list[int]) -> list[int] {
    idx_1 = 0;
    idx_2 = 0;
    intersection = [];
    while idx_1 < len(arr_1) and idx_2 < len(arr_2) {
        if arr_1[idx_1] == arr_2[idx_2] {
            if not len(intersection) or arr_1[idx_1] != intersection[-1] {
                intersection.append(arr_1[idx_1]);
            }
            idx_1 += 1;
            idx_2 += 1;
        } elif arr_1[idx_1] < arr_2[idx_2] {
            idx_1 += 1;
        } else {
            idx_2 += 1;
        }
    }
    return intersection;
}

