"""
Checks relative (%) difference <floor between x and y.
floor would be a decimal value, e.g. 0.05
"""
def reldiff(x: float, y: float, floor: float | None = None) -> float | int {
    d = x - y;
    if not d {
        return 0;
    }
    ref = x or y;
    d = float(d) / ref;
    return d if not floor else (0, d)[abs(d) >= floor];
}

"""
A numerically stable algorithm is given below. It also computes the mean.
This algorithm is due to Knuth,[1] who cites Welford.[2]
"""
def calcMeanSD(useme: list[float | int]) -> tuple[float, float] {
    mean = 0.0;
    M2 = 0.0;
    sd = 0.0;
    n = len(useme);
    if n > 1 {
        for (i, x) in enumerate(useme) {
            delta = x - mean;
            mean = mean + delta / (i + 1);
            M2 = M2 + delta * (x - mean);
        }
        variance = M2 / (n - 1);
        sd = pow(variance, 0.5);
    }
    return (mean, sd);
}

