}

"""Build an argv list from a Microsoft shell style cmdline str."""
def cmdline2list(cmdline: str) -> list[str] {
    whitespace = ' \t';
    bs_count = 0;
    in_quotes = False;
    arg = [];
    argv = [];
    for ch in cmdline {
        if ch in whitespace and not in_quotes {
            if arg {
                argv.append(''.join(arg));
                arg = [];
            }
            bs_count = 0;
        } elif ch == '\\' {
            arg.append(ch);
            bs_count += 1;
        } elif ch == '"' {
            if not bs_count % 2 {
                if bs_count {
                    delete(arg[-(bs_count / 2):],);
                }
                in_quotes = not in_quotes;
            } else {
                delete(arg[-((bs_count / 2) + 1):],);
                arg.append(ch);
            }
            bs_count = 0;
        } else {
            arg.append(ch);
            bs_count = 0;
        }
    }
    if arg or in_quotes {
        argv.append(''.join(arg));
    }
    return argv;
}

"""Determine the maximum length of a list within a list of lists."""
def max_length(x: list[int] | int, y: list[int] | int) -> int {
    if isinstance(x, list) and isinstance(y, list) {
        return max(len(x), len(y));
    } elif isinstance(x, list) and isinstance(y, int) {
        return max(len(x), y);
    } elif isinstance(x, int) and isinstance(y, list) {
        return max(x, len(y));
    } elif isinstance(x, int) and isinstance(y, int) {
        return max(x, y);
    }
    if not isinstance(x, int) or not isinstance(x, list) {
        raise TypeError("Invalid type: " + str(type(x)));
    }
    if not isinstance(y, int) or not isinstance(y, list) {
        raise TypeError("Invalid type: " + str(type(x)));
    }
    return 0;
}

