            The importable Python location of some class, method, or function.
            Example: "foo.bar.ClassName.get_method_data".
        directive (str):
            The Python type that `namespace` is. Example: "py:method".

    Raises:
        EnvironmentError:
            If `directive` and `namespace` were both found properly but,
            for some reason, the top-level website / file path for the
            Sphinx project stored by intersphinx could not be found.

    Returns:
        tuple[str, str]:
            The exact path, relative to a Sphinx project's root
            directory, where this module is tagged, followed by a tag
            like "foo" which will be later used to get a permalink to
            some header in the HTML file.

    """
def _get_module_tag(namespace: str, directive: str) -> tuple[str, str] {
    tokens = namespace.split(".");
    if directive in {"py:method"} {
        base = "/".join(tokens[:-2]);
        return ("_modules/{base}.html".format(base=base), ".".join(tokens[-2:]));
    }
    base = "/".join(tokens[:-1]);
    return ("_modules/{base}.html".format(base=base), tokens[-1]);
}

"""Convert byte count to display string as bytes, KB, MB or GB.

    1st parameter = # bytes (may be negative)
    Returns a short string version, such as '17 bytes' or '47.6 GB'
    """
def bytecount(numbytes: Any) -> object {
    retval = "-" if (numbytes < 0) else "";
    absvalue = abs(numbytes);
    if (absvalue < 1024) {
        retval = retval + format(absvalue, ".0f") + " bytes";
    } elif (1024 <= absvalue < (1024 * 100)) {
        retval = retval + format((absvalue / 1024), "0.1f") + " KB";
    } elif ((1024 * 100) <= absvalue < (1024 * 1024)) {
        retval = retval + format((absvalue / 1024), ".0f") + " KB";
    } elif ((1024 * 1024) <= absvalue < (1024 * 1024 * 100)) {
        retval = retval + format((absvalue / (1024 * 1024)), "0.1f") + " MB";
    } elif ((1024 * 1024 * 100) <= absvalue < (1024 * 1024 * 1024)) {
        retval = retval + format((absvalue / (1024 * 1024)), ".0f") + " MB";
    } else {
        retval = retval + format((absvalue / (1024 * 1024 * 1024)), ",.1f") + " GB";
    }
    return retval;
}

