    right: list[str],
    measurement: list[int | float],
    correction: int | float
) -> tuple[list[str], list[int | float]] {
    imagePaths = [];
    imagePaths.extend(center);
    imagePaths.extend(left);
    imagePaths.extend(right);
    measurements = [];
