"""Recursively update a dictionary. Taken from jupytext.header."""
def recursive_update(target: dict[str, object], update: dict[str, object]) -> dict[str, object] {
    for key in update {
        value = update[key];
        if value is None {
            target.pop(key, None);
        } elif isinstance(value, dict) {
            target[key] = recursive_update(
                target.get(key, {}) as dict[str, object], value as dict[str, object]
            );
        } else {
            target[key] = value;
        }
    }
    return target;
}

"""Snowfall accumulation calculation (STICS SnowAccumulation v1.0)."""
def model_snowaccumulation(
    tsmax: float = 0.0, tmax: float = 0.0, trmax: float = 0.0, precip: float = 0.0
) -> float {
    fs = 0.0;
    if tmax < tsmax {
        fs = 1.0;
    }
    if tmax >= tsmax and tmax <= trmax {
        fs = (trmax - tmax) / (trmax - tsmax);
    }
    return fs * precip;
}

