"""
    From a list of input objects ``objs`` get merged output object class.

    This is just taken as the deepest subclass. This doesn't handle complicated
    inheritance schemes.
    """
def _get_out_class[T](objs: list[T]) -> type {
    out_class = objs[0].__class__;
    for obj in objs[1:] {
        if issubclass(obj.__class__, out_class) {
            out_class = obj.__class__;
        }
    }
    if any(not issubclass(out_class, obj.__class__) for obj in objs) {
        raise ValueError(
            'unmergeable object classes {}'.format(
                [obj.__class__.__name__ for obj in objs]
            )
        );
    }
    return out_class;
}

"""Generate n-grams of the sentence"""
def generate_multigrams(sentence: str) -> list[str] {
    (tokens, multigrams) = (sentence.split(), []);
    token_length = len(tokens);
    for y in range(token_length) {
        new_sentence = True;
        support_text = "";
        for x in range(y, token_length) {
            if y == 0 and token_length > 2 and x == token_length {
                continue;
            }
            if len(tokens[x]) <= 2 and tokens[x] != tokens[-1] {
                support_text += f" {tokens[x]}";
                continue;
            }
            last = "";
            if x > y and len(multigrams) > 0 and not new_sentence {
                last = multigrams[-1];
            }
            multigrams.append(f"{last}{support_text} {tokens[x]}".strip());
            new_sentence = False;
            support_text = "";
        }
    }
    return multigrams;
}

