                    e.g., if the size given is 3, the goal is [[1,2,3],[4,5,6],[7,8,9]].
    """
def make_goal(s: int) -> list[list[int]] {
    arr = [i for i in range(1, s * s)];
    arr.append(0);
    return [[arr[i * s + j] for j in range(s)] for i in range(s)];
}

