"""
    Applies the predicate to each item, taking the disjunction of the results.
    Will add d as a disjunct, and then finally will take that in
    conjunction with c. Returns the value.
    """
def build_mask[T](
    items: list[T],
    predicate: Callable[[T], int],
    d: int | None = None,
    c: int | None = None
) -> int | None {
    q: int | None = None;
    for i in items {
        if q is None {
            q = predicate(i);
        } else {
            q |= predicate(i);
        }
    }
    if d is not None {
        q = d | q;
    }
    if c is not None {
        q = c & q;
    }
    return q;
}

"""Calculate Petzval sum of a multi-element lens.

    Args:
        ns (sequence): Refractive indices of all media.
        rocs (sequence): Length is one less than ns.

    Returns:
        Petzval sum.
    """
def calc_multi_element_lens_petzval_sum(ns: list[float], rocs: list[float]) -> float {
    assert len(ns) == len(rocs) + 1;
    ps = 0.0;
    for (n1, n2, roc) in zip(ns[:-1], ns[1:], rocs) {
        ps += (n2 - n1) / (roc * n1 * n2);
    }
    return ps;
}

