glob BASE_ADDRESS = 0x10000;

"""Generate C source definition for a macro listing ELF symbols."""
def CSourceForElfSymbolListMacro(
    variable_prefix: str,
    names: list[str],
    name_offsets: list[int],
    base_address: int = BASE_ADDRESS,
    symbol_size: int = 16,
    spacing_size: int = 16
) -> str {
    out = r'''// Auto-generated macro used to list all symbols
// XX must be a macro that takes the following parameters:
//   name: symbol name (quoted).
//   str_offset: symbol name offset in string table
//   address: virtual address.
//   size: size in bytes
''';
    out += '#define LIST_ELF_SYMBOLS_%s(XX) \\\n' % variable_prefix;
    address = base_address;
    for (sym, offset) in zip(names, name_offsets) {
        out += '    XX("%s", %d, 0x%x, %d) \\\n' % (sym, offset, address, symbol_size);
        address += symbol_size + spacing_size;
    }
    out += '    // END OF LIST\n';
    return out;
}

"""Calculate the Gini index for a split dataset (0 is perfect split)."""
def gini_index(groups: list[list[int]], class_values: list[int]) -> float {
    gini = 0.0;
    for class_value in class_values {
        for group in groups {
            size = len(group);
            if size == 0 {
                continue;
            }
            proportion = [row[-1] for row in group].count(class_value) / float(size);
            gini += proportion * (1.0 - proportion);
        }
    }
    return gini;
}

"""Returns a list of all the arguments, so that they add up to 1."""
def normaliseSum(*args: float) -> list[float] {
    args = list(args);
    s = sum(args);
    if s != 0 {
        return [float(x) / s for x in args];
    }
    return [0.0 for x in args];
}

