    thresh = min(feat_value) + percentile * (max(feat_value) - min(feat_value));
    if removeDirection == 'Below' {
        keep_planes = [z for z in planes if feature_dict[z] >= thresh];
    } else {
        keep_planes = [z for z in planes if feature_dict[z] <= thresh];
    }
    return set(keep_planes);
