""" map_from, map_to: strings where each contain
    N unique lowercase letters.
    code: string (assume it only contains letters also in map_from)
    Returns a tuple of (key_code, decoded).
    key_code is a dictionary with N keys mapping str to str where
    each key is a letter in map_from at index i and the corresponding
    value is the letter in map_to at index i.
    decoded is a string that contains the decoded version
    of code using the key_code mapping. """
def cipher(map_from: str, map_to: str, code: str) -> tuple[dict[str, str], str] {
    key_code = {};
    for i in range(len(map_from)) {
        key_code[map_from[i]] = map_to[i];
    }
    decoded = '';
    for char in code {
        decoded += key_code[char];
    }
    return (key_code, decoded);
}

"""
Returns an N-D array where each row represents a separate segmentation of continuous data with no gaps
greater than the max gap.
"""
def segment_times(timeseries: list[float], max_gap: float) -> list[list[float]] {
    time_segments = [];
    is_contiguous = False;
    arr_n = -1;
    for (i, t) in enumerate(timeseries) {
        if not is_contiguous {
            time_segments.append([t]);
            arr_n += 1;
        } else {
            time_segments[arr_n].append(t);
        }
        if i + 1 < len(timeseries) {
            is_contiguous = timeseries[i + 1] - t < max_gap;
        }
    }
    return time_segments;
}

glob MIN_TIME = 60;
glob HOUR_TIME = 3600;
glob DAY_TIME = 86400;

""" Convert number of seconds to human string - *d*h*m*s """
def secs_to_text(secs: int | float) -> str {
    secs = int(secs);
    days = 0;
    hours = 0;
    mins = 0;
    if secs >= DAY_TIME {
        days = int(secs / DAY_TIME);
        secs = secs % DAY_TIME;
    }
    if secs >= HOUR_TIME {
        hours = int(secs / HOUR_TIME);
        secs = secs % HOUR_TIME;
    }
    if secs >= MIN_TIME {
        mins = int(secs / MIN_TIME);
        secs = secs % MIN_TIME;
    }
    str_time = [];
    if days {
        str_time.append("{0}d".format(days));
    }
    if hours {
        str_time.append("{0}h".format(hours));
    }
    if mins {
        str_time.append("{0}m".format(mins));
    }
    if not len(str_time) or secs > 0 {
        str_time.append("{0}s".format(secs));
    }
    return " ".join(str_time);
}

