"""Expands the Haskell-like range given as a parameter
    into Python's `range` object. The range must be finite.

    Args:
        val (str): a range to expand.

    Returns:
        range: resulting range.

    Raises:
        ValueError: if given an invalid Haskell-like range.

    >>> expand_range("[1..10]")
    range(1, 11)

    >>> expand_range("[1,3..10]")
    range(1, 11, 2)

    >>> expand_range("[5,4..1]")
    range(5, 0, -1)
    """
def expand_range(val: Any) -> object {
    if (not val.startswith("[") or not val.endswith("]")) {
        raise ValueError("Invalid bracket placement");
    }
    val = val[1:-1];
    spl = val.split("..");
    if ((len(spl) != 2) or not all(spl)) {
        raise ValueError("Invalid range");
    }
    end = int(spl[1]);
    if ("," in spl[0]) {
        (begin, bstep) = map(int, spl[0].split(","));
        step = bstep - begin;
    } else {
        begin = int(spl[0]);
        step = 1;
    }
    if (step == 0) {
        raise ValueError("Zero step is not allowed");
    }
    if (step > 0) {
        end += 1;
    } else {
        end -= 1;
    }
    return range(begin, end, step);
}

"""
    Args:
        arr: heightmap array
        index_row: row index of location to check adjacent locations for lower or equally low height
        index_col: column index of location to check adjacent locations for lower or equally low height
    Returns:
        True if check location is lower than all adjacent locations, else False
    """
def check_for_lower_adj_height(arr: list[list[int]], index_row: int, index_col: int) -> bool {
    height = arr[index_row][index_col];
    if index_row >= 1 and height >= arr[index_row - 1][index_col] {
        return False;
    }
    if index_row < len(arr) - 1 and height >= arr[index_row + 1][index_col] {
        return False;
    }
    if index_col >= 1 and height >= arr[index_row][index_col - 1] {
        return False;
    }
    if index_col < len(arr[index_row]) - 1 and height >= arr[index_row][index_col + 1] {
        return False;
    }
    return True;
}

"""
    This function takes a pair of bounding boxes and returns intersection-over-
    union (IoU) of two bounding boxes.
    """
def compute_iou(box_1: tuple[int, int, int, int], box_2: tuple[int, int, int, int]) -> float {
    (tl_row_1, tl_col_1, br_row_1, br_col_1) = box_1;
    (tl_row_2, tl_col_2, br_row_2, br_col_2) = box_2;
    assert tl_row_1 < br_row_1;
    assert tl_col_1 < br_col_1;
    assert tl_row_2 < br_row_2;
    assert tl_col_2 < br_col_2;
    area_1 = (br_row_1 - tl_row_1) * (br_col_1 - tl_col_1);
    area_2 = (br_row_2 - tl_row_2) * (br_col_2 - tl_col_2);
    tl_row_i = max(tl_row_1, tl_row_2);
    tl_col_i = max(tl_col_1, tl_col_2);
    br_row_i = min(br_row_1, br_row_2);
    br_col_i = min(br_col_1, br_col_2);
    if br_row_i < tl_row_i or br_col_i < tl_col_i {
        intersection_area = 0;
    } else {
        intersection_area = (br_row_i - tl_row_i) * (br_col_i - tl_col_i);
    }
    union_area = area_1 + area_2 - intersection_area;
    iou = intersection_area / union_area;
    assert iou >= 0 and iou <= 1.0;
    return iou;
}

