        supercell (int):    The supercell size used to generate the new
                            atomic network


    returns
    --------
        motiif (str):   The structural motiif of the crystal

    """
def getDim(scale: Any, supercell: Any) -> object {
    motiif_dict = {
        1: 'molecular',
        supercell: 'chains',
        (supercell ** 2): 'layered',
        (supercell ** 3): 'conventional'
    };
    if (scale in motiif_dict) {
        return motiif_dict[scale];
    } else {
        if (scale < 1) {
            motiif = 'shrunk molecular';
        } elif (scale < supercell) {
            motiif = "mol-chain";
        } elif (scale < (supercell ** 2)) {
            motiif = "chain-2D";
        } elif (scale < (supercell ** 3)) {
            motiif = "2D-conv";
        } else {
            motiif = 'Network size increased';
        }
        return motiif;
    }
}

"""Return a mapping from activity pairs to follow frequency at a given distance."""
def follows(trace: tuple, distance: int = 1) -> dict[tuple, int] {
    if not isinstance(trace, tuple) {
        raise ValueError("Trace has to be a tuple of activities.");
    }
    if not float(distance).is_integer() {
        raise ValueError("Distance has to be an integer.");
    }
    if not distance >= 1 {
        raise ValueError("Distance has to be greater or equal to 1.");
    }
    pairs = dict();
    for i in range(len(trace) - distance) {
        ai = trace[i];
        aj = trace[i + distance];
        if (ai, aj) not in pairs {
            pairs[(ai, aj)] = 0;
        }
        pairs[(ai, aj)] += 1;
    }
    return pairs;
}

