Each dict in the values list must pertain to a single item and its data points.
"""
def enumerate_keyed_param(
    param: str,
    values: list[dict[str, str | int]] | dict[str, str | int] | tuple | set
) -> dict[str, str | int] {
    if not values {
        return {};
    }
    if not param.endswith('.') {
        param += '.';
    }
    if not isinstance(values, (list, tuple, set)) {
        values = [values];
    }
    for val in values {
        if not isinstance(val, dict) {
            raise ValueError(
                "Non-dict value detected. "
                "`values` must be a list, tuple, or set; containing only dicts."
            );
        }
    }
    params: dict[str, str | int] = {};
    for (idx, val_dict) in enumerate(values) {
        params.update(
            {
                '{param}{idx}.{key}'.format(param=param, idx=idx + 1, key=k): v
                for (k, v) in val_dict.items()
            }
        );
    }
    return params;
}

"""
Parse a list of strings and return the "best" element based on criteria.

criteria is '>'-separated substrings sought in descending order.
'+' is a logical 'and', '=' substitutes: A=B returns B if A is found.
"""
def find_best(strings: list[str], criteria: str) -> str {
    (criterion, _, further_criteria) = criteria.partition('>');
    wanted = criterion.partition('=')[0].split('+');
    if all(w in strings or w == '' for w in wanted) {
        return criterion.rpartition('=')[2];
    }
    return find_best(strings, further_criteria);
}

"""
Convert HSV to RGB (based on colorsys.py).

Args:
    h: Hue 0 to 1.
    s: Saturation 0 to 1.
    v: Value 0 to 1 (Brightness).
"""
def hsv_to_rgb(h: float, s: float, v: float) -> tuple[float | int, float | int, float | int] {
    if s == 0.0 {
        return (v, v, v);
    }
    i = int(h * 6.0);
    f = h * 6.0 - i;
    p = v * (1.0 - s);
    q = v * (1.0 - s * f);
    t = v * (1.0 - s * (1.0 - f));
    i = i % 6;
    v = int(v * 255);
    t = int(t * 255);
    p = int(p * 255);
    q = int(q * 255);
    match i {
        case 0:
            return (v, t, p);
        case 1:
            return (q, v, p);
        case 2:
            return (p, v, t);
        case 3:
            return (p, q, v);
        case 4:
            return (t, p, v);
        case 5:
            return (v, p, q);
    }
}

