"""Check whether the text contains a character that needs escaping."""
def needs_escaping(text: str) -> bool {
    for character in text {
        if character in ('\a', '\b', '\f', '\n', '\r', '\t', '\v', '"', '\\') {
            return True;
        }
    }
    return False;
}

"""Split a locale into three parts, for langauge, script, and region."""
def get_locale_parts(locale: str) -> tuple[str, str | None, str | None] {
    parts = locale.split('_');
    if len(parts) == 1 {
        return (parts[0], None, None);
    } elif len(parts) == 2 {
        if len(parts[1]) == 4 {
            return (parts[0], parts[1], None);
        }
        return (parts[0], None, parts[1]);
    }
    assert len(parts) == 3;
    return tuple(parts);
}

"""Return dict modelling a BundleConfig splitDimension entry."""
def _MakeSplitDimension(value: int | str, enabled: bool) -> dict[str, int | str | bool] {
    return {'value': value, 'negate': not enabled};
}

glob ASCII_UPPERCASE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';

"""Assign a cluster label (A–Z, AA, AB, …) from a cluster id."""
def get_cluster_label(cluster_id: int) -> str {
    cluster_label = '';
    current_index = cluster_id;
    while current_index >= 0 {
        if current_index < len(ASCII_UPPERCASE) {
            cluster_label += ASCII_UPPERCASE[current_index];
        } else {
            for letter in reversed(cluster_label) {
                if letter != 'Z' {
                    idx = ASCII_UPPERCASE.index(cluster_label[-1]);
                    cluster_label = cluster_label[:-1] + ASCII_UPPERCASE[idx + 1];
                    break;
                }
            } else {
                cluster_label = 'A' + cluster_label;
            }
        }
        current_index -= 26;
    }
    return cluster_label;
}

"""Encode an 8-bit unsigned integer."""
def u8(x: int) -> bytes {
    assert 0 <= x < 256;
    return x.to_bytes(1, byteorder='little');
}

"""Normalize Paizo HTML attribute names to a canonical form."""
def normalize_attribute(attr: str) -> str {
    attr = attr.strip();
    if attr.endswith(':') {
        attr = attr[:-1];
    }
    if attr == 'Prerequisites' {
        attr = 'Prerequisite';
    }
    if attr == 'Note' {
        attr = 'Prerequisite';
    }
    if attr == 'Benefits' {
        attr = 'Benefit';
    }
    if attr == 'Leadership Modifiers' {
        attr = 'Benefit';
    }
    assert attr in ('Prerequisite', 'Benefit', 'Normal', 'Special');
    return attr.lower();
}

"""
    Checks to see if 'eqsine' option is set to true

    Parameters
    ----------
    opts : dict
        Dictionary of :func:`pyyeti.srs.srs` options; can be empty.

    Returns
    -------
    flag : bool
        True if the eqsine option is set to true.
    """
def _is_eqsine(opts: Any) -> object {
    if ("eqsine" in opts) {
        return opts["eqsine"];
    }
    return False;
}

"""Convert degrees Fahrenheit to degrees Celsius."""
def conv_F2C(value: int | float) -> int | float {
    value_c = (value - 32) * (5 / 9);
    if hasattr(value_c, 'units') {
        getattr(value_c, 'attrs').update(units='degC');
    }
    return value_c;
}

"""Return times in seconds by adding HMS offset tuples to a start time."""
def sec_from_hms(start: int | float, *times: tuple[int, ...]) -> list[int | float] {
    ret = [];
    for t in times {
        cur = 0;
        if len(t) > 0 {
            cur += t[0] * 3600;
        }
        if len(t) > 1 {
            cur += t[1] * 60;
        }
        if len(t) > 2 {
            cur += t[2];
        }
        ret.append(start + cur);
    }
    return ret;
}

"""Order nodes by their topological order."""
def ts(nodes: list[str], topo_order: list[str]) -> list[str] {
    node_set = set(nodes);
    [n for n in topo_order if n in node_set]
}

"""
    Return true if s can be converted into a valid integer, and false otherwise.

    :param s: value to check if can be converted into a valid integer
    :return: true if s can be converted into a valid integer, false otherwise
    >>> is_valid_int("hello")
    False
    >>> is_valid_int("506")
    True
    """
def is_valid_int(s: str) -> bool {
    try {
        int(s);
    } except ValueError {
        return False;
    } else {
        return True;
    }
}

"""
    Get all non-library functions
    @param functions: List of db_DataTypes.dbFunction objects
    @return: a subset list of db_DataTypes.dbFunction objects that are not library functions.
    """
def get_non_lib(functions: Any) -> object {
    return [
        f
        for f in functions
        if not f.is_lib_func
    ];
}

"""argument of doc_string"""
def doc_arg(name: Any, brief: Any) -> object {
    return "    :param {0}: {1}".format(name, brief);
}

"""The closest tuples to tup: decrementing by 1 along any dimension.
Never go into negatives though."""
def decrementAny(tup: tuple[int, ...]) -> list[tuple[int, ...]] {
    res = [];
    for (i, x) in enumerate(tup) {
        if x > 0 {
            res.append(tuple(list(tup[:i]) + [x - 1] + list(tup[i + 1:])));
        }
    }
    return res;
}

"""
    Convert rmin/epsilon representation to AB representation of the LJ
    potential
    """
def _LJ_rminepsilon_to_ab(coeffs: Any) -> object {
    A = coeffs['epsilon'] * (coeffs['Rmin'] ** 12.0);
    B = 2 * coeffs['epsilon'] * (coeffs['Rmin'] ** 6.0);
    return {"A": A, "B": B};
}

"""Return the factorial of the given number."""
def fact(n: int) -> int {
    r = 1;
    while n > 0 {
        r = r * n;
        n = n - 1;
    }
    return r;
}

"""n-Significant Figures"""
def float_nsf(num: float | int | str, precision: int = 17) -> str {
    return ('{0:.%ie}' % (precision - 1)).format(float(num));
}

"""Must be a non-empty non-blank string"""
def non_empty_string(value: str) -> bool {
    return bool(value) and bool(value.strip());
}

"""
We can either take or leave the current number depending on previous max number
"""
def max_sum_naive(arr: list[int], length: int, index: int, prev_max: int) -> int {
    if index >= length {
        return 0;
    }
    cur_max = 0;
    if arr[index] > prev_max {
        cur_max = arr[index] + max_sum_naive(arr, length, index + 1, arr[index]);
    }
    return max(cur_max, max_sum_naive(arr, length, index + 1, prev_max));
}

"""Make the authorization headers to communicate with endpoints which implement Auth0 authentication API.

    Args:
        auth_token (dict): a dict obtained from the Auth0 domain oauth endpoint, containing the signed JWT
            (JSON Web Token), its expiry, the scopes granted, and the token type.

    Returns:
        headers (dict): A dict representing the headers with necessary token information to talk to Auth0 authentication
            required endpoints.
    """
def make_auth_header(auth_token: Any) -> object {
    token_type = auth_token['token_type'];
    access_token = auth_token['access_token'];
    headers = {
        "Content-type": "application/json",
        "Authorization": "{token_type} {access_token}".format(
            token_type=token_type, access_token=access_token
        )
    };
    return headers;
}

"""Auxiliary function to sort the contributions for the compare_plot.
Returns the value of the maximum difference between values in contributions[0]."""
def maximum_difference_sort_value(contributions: list[list[float]]) -> float {
    vals = contributions[0];
    if len(vals) <= 1 {
        return vals[0];
    }
    return max([
        abs(contrib_i - contrib_j)
        for (i, contrib_i) in enumerate(vals)
        for (j, contrib_j) in enumerate(vals)
        if i <= j
    ]);
}

"""Returns a copy of the given board_state with the desired move applied."""
def apply_move(
    board_state: tuple[tuple[int, int, int], tuple[int, int, int], tuple[int, int, int]],
    move: tuple[int, int],
    side: int
) -> tuple[tuple[int, int, int], tuple[int, int, int], tuple[int, int, int]] {
    (move_x, move_y) = move;
    rows: list[tuple[int, int, int]] = [];
    for x in range(3) {
        if move_x == x {
            temp = list(board_state[x]);
            temp[move_y] = side;
            rows.append(tuple(temp));
        } else {
            rows.append(board_state[x]);
        }
    }
    return tuple(rows);
}

""" Returns a filtered list with strings that end with '.pdf'

    Keyword arguments:
    filepaths -- List of filepath strings
    """
def filter_pdf_files(filepaths: Any) -> object {
    return [
        x
        for x in filepaths
        if x.endswith('.pdf')
    ];
}

"""Get the experiment type from the filename (timestamp removed)."""
def get_experiment_type(filename: str) -> str {
    file_type = '';
    filename = filename.split('/')[-1];
    elements = filename.split('_');
    for i in range(len(elements) - 3) {
        file_type += '{}_'.format(elements[i]);
    }
    return file_type[:-1];
}

"""Format statistics for printing to a table."""
def format_stats(stats: dict[str, str | int | float]) -> str {
    result = '';
    for (key, value) in stats.items() {
        result += f'{key} - {value}\n';
    }
    return result[:-1];
}

"""m*wavelength = neff * delta_length."""
def get_mzi_delta_length(m: float, neff: float = 2.4, wavelength: float = 1.55) -> float {
    return m * wavelength / neff;
}

"""Strip any whitespace then outer characters."""
def parse_tuple(tuple_string: str) -> str {
    return tuple_string.strip().strip("\"[]");
}

"""Remove trailing zeroes in `t`."""
def rstrip_tuple(t: tuple[int, ...]) -> tuple[int, ...] {
    if not t or t[-1] {
        return t;
    }
    right = len(t) - 1;
    while right > 0 and t[right - 1] == 0 {
        right -= 1;
    }
    return t[0:right];
}
